SET LOCAL smc.source = 'n8n';
SET LOCAL smc.reason = 'W25 Paystack codes written back';
-- Only writes when the code actually changed: every pricing write fires pg_notify('pricing_changed') -> W25.
update public.pricing set paystack_page_code = case when $2 = 'page' then $3 else paystack_page_code end,
  paystack_plan_code = case when $2 = 'plan' then $3 else paystack_plan_code end
